/* From Uiverse.io by reshades - Tags: checkbox, clean */
.__UIV_SCOPE__ .container input {
  position: absolute;
  opacity: 0;
  cursor: pointer;
  height: 0;
  width: 0;
}

.__UIV_SCOPE__ .container {
  display: block;
  position: relative;
  cursor: pointer;
  font-size: 20px;
  user-select: none;
}

.__UIV_SCOPE__ .checkmark {
  position: relative;
  top: 0;
  left: 0;
  height: 1.3em;
  width: 1.3em;
  background-color: #ffffff00;
  border-radius: 5px;
  border: #fff 1px solid;
  transition: all 0.2s;
}

.__UIV_SCOPE__ .checkmark2 {
  position: relative;
  top: 0.12em;
  left: 0.12em;
  height: 1.0em;
  width: 1.0em;
  background-color: #ffffff00;
  border-radius: 111px;
  border: #fff 1px solid;
  transition: all 0.2s;
}

.__UIV_SCOPE__ .container input:checked ~ .checkmark {
  background-color: #4346ff;
  border: #4346ff 1px solid
}
